// Original authenticated Actions router, with a real loopback bootstrap + main SDK.
fn only_owner_http_body()->serde_json::Value{serde_json::json!({"expected_revision":1,"nonce":"a".repeat(32),"name":"private-single-group","group_type":1,"properties":[],"consent":true,"write_consent":true,"session_owner_consent":true,"properties_read_consent":true})}
#[tokio::test]
async fn owner_only_http_requires_auth_current_account_and_never_accepts_uid_uri_or_members(){
 let st=build_test_router().await.expect("Actions private D-Bus required");let served=serve(st.router.clone()).await;let path="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef/groups/create/owner-only";let(s,_,_)=account_request(&served,reqwest::Method::POST,path,Some(only_owner_http_body()),None).await;assert_eq!(s,StatusCode::UNAUTHORIZED);let cookie=authenticate(&served).await;
 for key in ["expected_owner_uid","uid","login_uri","first","members","token","group_id","clear_unknown"]{let mut body=only_owner_http_body();body[key]=serde_json::json!("fixture-private");let(s,h,b)=account_request(&served,reqwest::Method::POST,path,Some(body),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_secrets(&b);no_store(&h);}for key in ["consent","write_consent","session_owner_consent"]{let mut body=only_owner_http_body();body[key]=serde_json::json!(false);let(s,_,b)=account_request(&served,reqwest::Method::POST,path,Some(body),Some(&cookie)).await;assert_eq!(s,StatusCode::FORBIDDEN);no_secrets(&b);}assert!(st.app.app_accounts.list(100).await.unwrap().is_empty());
}
#[tokio::test]
async fn owner_only_http_rejects_alias_overrides_bad_enum_and_wrong_endpoint_before_admission(){
 let st=build_test_router().await.expect("Actions private D-Bus required");let served=serve(st.router.clone()).await;let cookie=authenticate(&served).await;let prefix="/api/non-3gpp/accounts/app-account-0123456789abcdef0123456789abcdef";
 for mode in 0..6{let mut v=only_owner_http_body();let mut suffix="groups/create/owner-only";match mode{0=>v["group_type"]=serde_json::json!(5),1=>v["properties"]=serde_json::json!([{"key":"Name","value":"private"}]),2=>v["properties"]=serde_json::json!([{"key":"Permission","value":1},{"key":"Group.Org.JoinAuth","value":"same"}]),3=>v["nonce"]=serde_json::json!("A".repeat(32)),4=>suffix="groups/create",_=>{suffix="group-management";v=group_management_http_body();v["operation"]=serde_json::json!("create_owner_only");}}let(s,h,b)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/{suffix}"),Some(v),Some(&cookie)).await;assert_eq!(s,StatusCode::BAD_REQUEST);no_store(&h);no_secrets(&b);}
}
#[tokio::test]
async fn owner_only_http_actual_bootstrap_create_read_and_history_never_export_principal_or_redial(){Box::pin(async{
 use crate::connectivity::app_voice::providers::jegotrip::group_owner_only_test_support as fixture;
 let st=build_test_router().await.expect("Actions private D-Bus required");let served=serve(st.router.clone()).await;let cookie=authenticate(&served).await;let cert=Certificates::generate("IP:127.0.0.1");let listener=tokio::net::TcpListener::bind((std::net::Ipv4Addr::LOCALHOST,0)).await.unwrap();let port=listener.local_addr().unwrap().port();let(s,_,b)=account_request(&served,reqwest::Method::POST,"/api/non-3gpp/accounts",Some(serde_json::json!({"provider_id":"app_voice","config":fixture::account_json(&cert.root,port)})),Some(&cookie)).await;assert_eq!(s,StatusCode::CREATED);let line=created_line(&b);let prefix=format!("/api/non-3gpp/accounts/{line}");let(tx,rx)=tokio::sync::oneshot::channel();let peer=tokio::spawn(Box::pin(fixture::serve(listener,cert.server_config(&tokio_rustls::rustls::version::TLS13),st.app.database.clone(),line.clone(),fixture::Flow::ConfirmRead,rx)));
 let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/start"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::ACCEPTED);tokio::time::timeout(std::time::Duration::from_secs(6),async{while st.app.app_accounts.get(&line,100).await.unwrap().phase!="hosted"{tokio::task::yield_now().await;}}).await.unwrap();let mut id=None;
 for fresh in [true,false]{let(s,h,b)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/groups/create/owner-only"),Some(only_owner_http_body()),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);no_secrets(&b);for secret in ["private-single-group","not-the-owner-first","account-domain.invalid","711111111_822222222","811111111-922222222",&"a".repeat(32)]{assert!(!b.contains(secret));}let v:serde_json::Value=serde_json::from_str(&b).unwrap();let write=&v["data"]["write"];assert_eq!(write["state"],"confirmed");assert_eq!(write["management"],serde_json::json!({"operation":"create_owner_only","properties":2}));assert_eq!(write["base_time"],"-7");assert_eq!(write["update_time"],"12");let read=&v["data"]["properties_read"];if fresh{id=write["id"].as_i64();assert_eq!(read["state"],"observed");assert_eq!(read["properties"],0);}else{assert!(id.is_some()&&id==write["id"].as_i64());assert_eq!(read["state"],"not_attempted");assert!(read["properties"].is_null());}}
 let(s,h,b)=account_request(&served,reqwest::Method::GET,&format!("{prefix}/relation-writes?limit=128"),None,Some(&cookie)).await;assert_eq!(s,StatusCode::OK);no_store(&h);no_secrets(&b);assert!(!b.contains("properties_read"));assert_eq!(st.app.database.get_recent_app_events(Some(&line),128).unwrap().iter().filter(|e|e.event_type=="app_voice.group_created").count(),1);tx.send(()).unwrap();let(s,_,_)=account_request(&served,reqwest::Method::POST,&format!("{prefix}/stop"),Some(serde_json::json!({"expected_revision":1})),Some(&cookie)).await;assert_eq!(s,StatusCode::OK);peer.await.unwrap();assert!(!st.app.app_accounts.get(&line,100).await.unwrap().io_cleanup_required);
}).await;}
